import { WorldProtocol, OperationResult } from "../../schema";
import { WorldState, createInitialWorld } from "./world";
import { advanceVok1, advanceVok2, resetVok } from "./vok/rules";
import { advanceZef1, advanceZef2 } from "./zef/rules";
import { advanceTal1 } from "./tal/rules";
import { advanceFen1, advanceFen2 } from "./fen/rules";
import { advanceOsk1 } from "./osk/rules";

function operationFailure(error: unknown): OperationResult {
  return {
    success: false,
    error: error instanceof Error ? error.message : String(error),
  };
}

export const protocol: WorldProtocol = {
  reset(): WorldState {
    return createInitialWorld();
  },

  applyOperation(
    state: WorldState,
    operationDisplayName: string
  ): OperationResult {
    try {
      let newState: WorldState;
      switch (operationDisplayName) {
        case "advanceVok1":
          newState = advanceVok1(state);
          break;
        case "advanceVok2":
          newState = advanceVok2(state);
          break;
        case "resetVok":
          newState = resetVok(state);
          break;
        case "advanceZef1":
          newState = advanceZef1(state);
          break;
        case "advanceZef2":
          newState = advanceZef2(state);
          break;
        case "advanceTal1":
          newState = advanceTal1(state);
          break;
        case "advanceFen1":
          newState = advanceFen1(state);
          break;
        case "advanceFen2":
          newState = advanceFen2(state);
          break;
        case "advanceOsk1":
          newState = advanceOsk1(state);
          break;
        default:
          return operationFailure(
            new Error(`Unknown operation: ${operationDisplayName}`)
          );
      }
      return { success: true, newState };
    } catch (error) {
      return operationFailure(error);
    }
  },

  getEntityState(state: WorldState, entityDisplayName: string): string {
    switch (entityDisplayName) {
      case "Vok":
        return state.vok;
      case "Zef":
        return state.zef;
      case "Tal":
        return state.tal;
      case "Fen":
        return state.fen;
      case "Osk":
        return state.osk;
      default:
        throw new Error(`Unknown entity: ${entityDisplayName}`);
    }
  },

  toAbstractSnapshot(state: WorldState): Record<string, string> {
    return {
      Vok: state.vok,
      Zef: state.zef,
      Tal: state.tal,
      Fen: state.fen,
      Osk: state.osk,
    };
  },
};
